def compute(vars):
    claim = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None

    percentage = (claim / total) * 100

    return {
        "value": percentage,
        "trace": {
            "claim": claim,
            "total": total,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
